const App=(()=>{
 'use strict';
 const $=id=>document.getElementById(id);
 const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 const prior=n=>new Date((Fin.day(today())-n)*86400000).toISOString().slice(0,10);
 const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const native=typeof LocalDevice!=='undefined';
 let state=Fin.blank(),page='overview',filter='all',hidden=false,storageError=false,ledgerFilter='all',ledgerMonth=today().slice(0,7),ledgerImportDraft={text:'',rows:[],errors:[]};
 const money=n=>hidden?'••••':new Intl.NumberFormat('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100);
 const pct=n=>n===null?'—':(n*100).toFixed(2)+'%';
 const meta={cash:['现金账户','▤'],investment:['投资理财','↗'],item:['贵重物品','◇'],debt:['负债','▥']};
 const types={income:'收入',expense:'支出',transfer:'转账',deposit:'投资追加',withdraw:'投资取出'};
 function toast(s){$('toast').style.pointerEvents='none';$('toast').textContent=s;$('toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{$('toast').style.opacity=0;$('toast').style.pointerEvents='none';},5000);}
 function persist(s){Fin.validate(s);const json=JSON.stringify(s);if(native){if(!LocalDevice.save(json))throw Error('保存失败，数据未修改');}else localStorage.setItem('squirrelfin.v1',json);state=s;storageError=false;render();}
 function invalidate(s,t){for(const a of s.assets.filter(a=>a.id===t.asset||a.id===t.to))a.snapshots.filter(v=>v.date>=t.date).forEach(v=>v.confirmed=false);}
 function change(fn){const s=JSON.parse(JSON.stringify(state));const before=new Set(s.transactions.map(t=>t.id));fn(s);s.transactions.filter(t=>!before.has(t.id)).forEach(t=>invalidate(s,t));persist(s);}
 function modal(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal').classList.remove('light-entry');$('modal').classList.toggle('has-form',html.includes('id="entry-form"'));if(!$('modal').open)$('modal').showModal();$('modal-body').scrollTop=0;}
 const close=()=>$('modal').close();
 function back(){if($('modal').open){close();return true;}if(page!=='overview'){page='overview';render();return true;}return false;}
 const btn=(action,label,cls='primary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
 const empty=(title,desc,action,label)=>`<div class="empty"><div class="empty-symbol">♧</div><h3>${title}</h3><div class="muted">${desc}</div>${action?btn(action,label):''}</div>`;
 function totals(at=today()){const t={cash:0,investment:0,item:0,debt:0};state.assets.forEach(a=>t[a.kind]+=Fin.balance(state,a,at));t.financial=t.cash+t.investment-t.debt;t.net=t.financial+t.item;return t;}
 function row(a){const last=[...a.snapshots].sort((x,y)=>x.date.localeCompare(y.date)).at(-1);return `<div class="row clickable" data-action="detail" data-id="${esc(a.id)}" role="button" tabindex="0"><div class="asset-icon ${a.kind}">${meta[a.kind][1]}</div><div class="row-main"><h3>${esc(a?.name||'仅记收支')}</h3><div class="muted">${esc(a.place||'未填写位置')}<span class="tag">${esc(a.risk)}</span></div></div><div class="row-right"><div class="money">${a.kind==='debt'?'−':''}¥ ${money(Fin.balance(state,a,today()))}</div><div class="muted">${last.date.slice(5)} 更新</div></div></div>`;}
 function nav(){const tabs=[['overview','◫','总览'],['assets','▤','资产'],['ledger','≡','记账'],['plans','↻','定投']];const html=tabs.map(([p,icon,label])=>`<a href="#${p}" class="nav-link ${page===p?'active':''}" data-action="nav" data-page="${p}"><span class="nav-symbol">${icon}</span>${label}</a>`).join('');$('desktop-nav').innerHTML=html;$('mobile-nav').innerHTML=html;}
 function overview(){const t=totals(),gross=Math.max(0,t.cash)+Math.max(0,t.investment)+Math.max(0,t.item),parts=[['现金账户',t.cash],['投资理财',t.investment],['实物残值',t.item]];const pending=state.plans.reduce((n,p)=>n+Fin.planStats(state,p,today()).pending.filter(d=>!state.executions.some(e=>e.plan===p.id&&e.date===d)).length,0),stale=state.assets.filter(a=>!a.sold&&Fin.day(today())-Fin.day([...a.snapshots].sort((x,y)=>x.date.localeCompare(y.date)).at(-1).date)>90).length;
 return `${state.demo?'<div class="demo-label">示例账本 · 数据与备份中可清空</div>':''}${!state.assets.length?`<section class="card welcome"><h2>随手记下第一笔</h2><p class="muted">无需设置账户，直接记录收入和支出。</p>${btn('add-tx','记一笔')} ${btn('demo','体验示例','secondary')}</section>`:''}<section class="hero"><div class="hero-top"><span class="hero-label">金融净资产</span><span class="pill">只存本地</span></div><div class="hero-amount"><span class="currency">¥</span>${money(t.financial)}</div><div class="hero-bottom"><div><small>含实物估值净资产</small><strong>¥ ${money(t.net)}</strong></div><div><small>负债</small><strong>¥ ${money(t.debt)}</strong></div></div></section><div class="quick-actions">${btn('add-tx','＋ 记一笔','quick-action main-action')}${btn('add-asset','登记资产','quick-action')}${btn('add-plan','设置定投','quick-action')}</div>${pending||stale?`<section class="card compact-card"><div class="section-head"><h2>待处理</h2></div>${pending?`<div class="row"><div class="row-main"><h3>${pending} 期定投待确认</h3></div>${btn('nav','去确认','secondary','data-page="plans"')}</div>`:''}${stale?`<div class="row"><div class="row-main"><h3>${stale} 项资产估值超过 90 天</h3></div>${btn('nav','去更新','text-button','data-page="assets"')}</div>`:''}</section>`:''}<section class="card recent-assets"><div class="section-head"><h2>我的资产</h2>${btn('nav','全部 →','text-button','data-page="assets"')}</div>${state.assets.slice(0,3).map(row).join('')||'<p class="muted">资产可按需登记，收支可以直接记录。</p>'}</section><section class="card fold-card"><h3>财富分布与提醒</h3><div class="allocation">${parts.map((p,i)=>`<span class="alloc-${i}" data-allocation="${gross?Math.max(0,p[1])/gross*100:0}"></span>`).join('')}</div>${parts.map(([n,v],i)=>`<div class="legend-row"><span>${n}</span><span>¥ ${money(v)} · ${gross?Math.round(Math.max(0,v)/gross*100):0}%</span></div>`).join('')}<p class="disclosure">按当前记录估值统计，实物残值并非可立即取用的现金。</p>${tips()}</section>`;}
 function assets(){return `<div class="toolbar"><div class="tabs">${[['all','全部'],['cash','现金'],['investment','投资'],['item','实物'],['debt','负债']].map(([f,l])=>btn('filter',l,`tab ${filter===f?'active':''}`,`data-filter="${f}"`)).join('')}</div>${btn('add-asset','＋ 登记')}</div><div class="card">${state.assets.filter(a=>filter==='all'||a.kind===filter).map(row).join('')||empty('还没有这类资产','为每份财富登记金额、位置和风险标签。','add-asset','登记资产')}</div><div class="disclosure">估值按当天结束时记录；同日流水视为已包含在该估值中。风险标签为手工记录，不代表产品评级。</div>`;}
 function ledger(){const month=ledgerMonth,summary=Fin.expenseSummary(state,month),ts=[...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)).filter(t=>t.date.slice(0,7)===month&&(ledgerFilter==='all'||ledgerFilter==='expense'&&t.type==='expense'&&!t.linked||ledgerFilter==='fixed'&&t.type==='expense'&&!t.linked&&t.nature==='fixed'));const templates=state.expenseTemplates||[];
 return `<div class="toolbar"><span class="muted">${month} · 收支</span><div class="toolbar-actions">${btn('ledger-import','导入','secondary')}${btn('add-tx','＋ 记一笔')}</div></div><section class="card spending-summary"><div class="section-head"><span class="muted">已记录支出</span><input id="ledger-month" type="month" aria-label="统计月份" value="${month}" max="${today().slice(0,7)}"></div><strong>¥ ${money(summary.total)}</strong><div class="muted">固定 ¥ ${money(summary.natures.fixed)} · 日常 ¥ ${money(summary.natures.variable)} · 偶发 ¥ ${money(summary.natures.occasional)}${summary.natures.unclassified?' · 含未分类记录':''}</div><section><h3>按用途查看</h3>${Object.entries(summary.categories).map(([c,v])=>`<div class="legend-row"><span>${esc(c)}</span><span>¥ ${money(v)}</span></div>`).join('')||'<p class="muted">本月还没有支出。</p>'}</section></section>${templates.length?`<section class="card fold-card"><h3>常用支出 · ${templates.length} 项</h3><p class="disclosure">点选带入资料，确认保存后才计入支出；不会自动扣款。</p>${templates.map(t=>`<div class="row"><div class="row-main"><h3>${esc(t.name)}</h3><div class="muted">${esc(t.category)} · ${Fin.expenseNatures[t.nature]}${t.frequency==='none'?'':t.frequency==='monthly'?' · 每月':' · 每年'} · ¥ ${money(t.amount)}</div></div>${btn('use-template','记一笔','secondary',`data-id="${esc(t.id)}"`)}</div>`).join('')}<section><h3>管理模板</h3>${templates.map(t=>`<div class="row"><span class="row-main">${esc(t.name)}</span>${btn('delete-template','删除模板','text-button danger',`data-id="${esc(t.id)}"`)}</div>`).join('')}</section></section>`:''}<div class="tabs ledger-tabs">${[['all','全部'],['expense','支出'],['fixed','固定支出']].map(([v,l])=>btn('ledger-filter',l,'tab '+(v===ledgerFilter?'active':''),`data-filter="${v}"`)).join('')}</div><div class="card">${ts.map(t=>{const a=state.assets.find(a=>a.id===t.asset),to=state.assets.find(a=>a.id===t.to);return `<div class="row clickable" role="button" tabindex="0" data-action="tx-detail" data-id="${esc(t.id)}"><div class="asset-icon">${t.type==='transfer'?'⇄':['income','deposit'].includes(t.type)?'＋':'−'}</div><div class="row-main"><h3>${esc(t.note||t.category||types[t.type])}</h3><div class="muted">${t.date} · ${esc(a?.name||'仅记收支')}${to?' → '+esc(to.name):''}</div><div class="muted">${t.linked?'定投资金转出':types[t.type]}${t.type==='expense'&&!t.linked?' · '+esc(t.category||'未分类')+' · '+(Fin.expenseNatures[t.nature]||'性质未分类'):''}</div></div><div class="row-right money">${['income','deposit'].includes(t.type)?'+':t.type==='transfer'?'':'−'}¥ ${money(t.amount)}</div></div>`;}).join('')||empty('还没有记录','保存一笔实际发生的收支。','add-tx','记一笔')}</div><section class="inline-help"><h3>记账与余额说明</h3><p>内部转账和定投资金转出不计入消费支出。旧记录保留为未分类，可在详情中补充。仅记收支不会改变资产余额。关联资产的流水不能早于初始盘点；同日流水已包含在日末估值中。</p></section>`;}
 function txDetail(id){const t=state.transactions.find(t=>t.id===id),a=state.assets.find(a=>a.id===t.asset),locked=t.linked||state.transactions.some(x=>x.linked===id)||state.executions.some(e=>e.transaction===id||e.sourceTransaction===id)||state.assets.some(a=>a.sold===id);modal('流水详情',`<div class="muted">${types[t.type]} · ${t.date} · ${esc(a?.name||'仅记收支')}</div><div class="detail-value">¥ ${money(t.amount)}</div><p>${esc(t.note||'无备注')}</p>${t.sourceCategory?`<p class="muted">原分类：${esc(t.sourceCategory)}</p>`:''}${t.type==='expense'&&!t.linked?`<p>${esc(t.category||'未分类')} · ${Fin.expenseNatures[t.nature]||'性质未分类'}</p>`:''}${t.to?`<p>转入：${esc(state.assets.find(a=>a.id===t.to).name)}</p>`:''}${locked?'<p class="disclosure">关联定投或出售记录需保持一致；定投修改可删除关联流水后重新确认。</p>':btn('edit-tx','编辑记录','primary',`data-id="${esc(id)}"`)}<section class="inline-help"><h3>更多操作</h3>${btn('delete-tx','删除流水','text-button danger',`data-id="${esc(id)}"`)}</section>`);}
 function plans(){return `<div class="toolbar"><span class="muted">到期后，确认实际成交</span>${btn('add-plan','＋ 定投')}</div>${state.plans.map(p=>{const s=Fin.planStats(state,p,today()),a=state.assets.find(a=>a.id===p.asset),pending=s.pending.filter(d=>!state.executions.some(e=>e.plan===p.id&&e.date===d)),history=state.executions.filter(e=>e.plan===p.id).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="card plan-card"><h2>${esc(p.name)}</h2><p class="muted">${esc(a?.name||'仅记收支')} · ${p.frequency==='monthly'?'每月':p.frequency==='weekly'?'每周':'每天'} · ¥ ${money(p.amount)}</p>${pending.slice(0,6).map(date=>`<div class="plan-todo"><span>${date} <span class="badge">待确认</span></span>${btn('execute','确认执行','primary',`data-id="${esc(p.id)}" data-date="${date}"`)}</div>`).join('')}${pending.length>6?'<p class="disclosure">先显示最早 6 期，处理后继续显示后续待办。</p>':''}${!pending.length?`<p class="muted">${s.due?'暂无待处理期次':'首期尚未到期'}</p>`:''}<div class="muted plan-summary">已成交 ${s.done}/${s.due} 期 · 确认投入 ¥ ${money(s.actual)}</div><section class="inline-help"><h3>执行历史与计划管理</h3><p class="disclosure">${p.start} 开始${p.end?' · '+p.end+' 结束':''} · 金额完成率 ${s.expected?pct(s.actual/s.expected):'—'} · 不自动扣款</p>${history.map(e=>`<div class="row"><div class="row-main"><h3>${e.date} · ${e.status==='confirmed'?'已成交':e.status==='failed'?'扣款失败':'已跳过'}</h3><div class="muted">${e.status==='confirmed'?e.actualDate+' 成交 · ¥ '+money(e.amount):'未记投入'}</div></div>${e.status==='confirmed'?btn('tx-detail','查看','text-button',`data-id="${esc(e.transaction)}"`):btn('execute','修改','text-button',`data-id="${esc(p.id)}" data-date="${e.date}"`)}</div>`).join('')||'<p class="muted">暂无执行记录。</p>'}${btn('delete-plan','删除计划','text-button danger',`data-id="${esc(p.id)}"`)}</section></section>`;}).join('')||`<div class="card">${empty('设置第一笔定投','计划与实际投入分开记录。','add-plan','设置定投')}</div>`}`;}
 function tips(){if(!state.assets.length)return '';const t=totals(),gross=t.cash+t.investment;const investments=state.assets.filter(a=>a.kind==='investment');const largest=investments.sort((a,b)=>Fin.balance(state,b,today())-Fin.balance(state,a,today()))[0];let advice='';if(gross>0)advice+=`<div class="callout">现金占已登记金融资产的 ${pct(t.cash/gross)}。结合近期支出检查应急资金是否足够；余额不等于所有资金都能立即取用。</div>`;if(largest&&gross>0)advice+=`<div class="callout">「${esc(largest.name)}」占已登记金融资产的 ${pct(Fin.balance(state,largest,today())/gross)}。定期检查单项资产集中度与自身风险承受能力。</div>`;if(t.debt>0)advice+=`<div class="callout">已登记负债 ¥ ${money(t.debt)}。核对到期时间与还款资金，避免只看资产余额。</div>`;if(!advice)advice='<div class="callout">按需登记资产、负债和估值，才能更准确地检查财富分布。</div>';return `<section class="card wealth-tips"><div class="section-head"><h2>财富小建议</h2><span class="muted">根据本地记录计算</span></div>${advice}<div class="disclosure">提醒依据仅来自已登记资产，不包含未记录的收入、支出或账户；风险标签由你填写。</div></section>`;}
 function render(){nav();$('page-title').textContent={overview:'我的财富',assets:'资产台账',ledger:'收支记录',plans:'定投计划'}[page];$('header-date').textContent=today().replaceAll('-',' / ')+' · SQUIRRELFIN';$('privacy').textContent=hidden?'◎':'◉';$('privacy').setAttribute('aria-label',hidden?'显示金额':'隐藏金额');$('content').innerHTML=({overview,assets,ledger,plans})[page]();document.querySelectorAll('[data-progress]').forEach(e=>e.style.width=Math.min(100,Number(e.dataset.progress))+'%');document.querySelectorAll('[data-allocation]').forEach(e=>e.style.width=e.dataset.allocation+'%');}
 const options=as=>as.map(a=>`<option value="${esc(a.id)}">${esc(a?.name||'仅记收支')}</option>`).join('');
 const dateField=(name='date',value=today(),title='日期')=>`<label>${title}</label><input name="${name}" type="date" value="${esc(value)}" max="${today()}" required>`;
 function form(title,body,submit,label='保存记录'){modal(title,`<form id="entry-form"><div class="form-content">${body}</div><div class="submit-area"><div class="form-error" id="form-error" role="alert"></div><div class="form-actions">${btn('close','取消','secondary')}<button type="submit" class="primary">${label}</button></div></div></form>`);const f=$('entry-form');f.querySelectorAll('input,select,textarea').forEach(el=>{el.id='field-'+el.name;if(el.previousElementSibling?.tagName==='LABEL')el.previousElementSibling.htmlFor=el.id;});let submitting=false;f.addEventListener('submit',e=>{e.preventDefault();if(submitting)return;submitting=true;try{const next=submit(Object.fromEntries(new FormData(e.target)));close();toast('已保存到本地');if(typeof next==='function')next();}catch(error){submitting=false;$('form-error').textContent=error.message;}});f.addEventListener('focusin',e=>{if(e.target.matches('input,select,textarea'))requestAnimationFrame(()=>e.target.scrollIntoView({block:'nearest'}));});}
 function toggleFields(selector,show){const section=$('entry-form').querySelector(selector);section.hidden=!show;section.querySelectorAll('input,select,textarea').forEach(e=>e.disabled=!show);}
 const more=(label,body)=>`<section class="inline-help"><h3>${label}</h3>${body}</section>`;
 function positive(v){const n=Fin.cents(v);if(n<=0)throw Error('金额需大于 0');return n;}
 function checkDate(d){if(!Fin.validDate(d)||d>today())throw Error('请选择有效日期，不能晚于今天');}
 function addAsset(config={}){if(!config||config instanceof Element)config={};const initial=config.kind||'cash';form('登记资产',`<div class="fields"><div><label>类型</label><select name="kind">${Object.entries(meta).map(([k,m])=>`<option value="${k}" ${k===initial?'selected':''}>${m[0]}</option>`).join('')}</select></div><div><label>资产名称</label><input name="name" maxlength="50" placeholder="例如：工资卡" required></div></div><label id="asset-value-label">初始余额（元）</label><input name="value" inputmode="decimal" placeholder="0.00" required>${dateField('date',config.date||today(),'初始盘点日期')}<p class="disclosure" id="asset-boundary">填写当天后续记账前的余额。</p>${more('更多资料（可选）',`<label>存放平台 / 地点</label><input name="place" maxlength="80" placeholder="例如：支付宝"><div id="asset-risk"><label>风险标签（个人记录）</label><select name="risk">${['未知 / 未评估','低风险','中低风险','中风险','中高风险','高风险'].map(r=>`<option>${r}</option>`).join('')}</select></div><div id="asset-cost"><label>购入成本（元，可选）</label><input name="cost" inputmode="decimal" placeholder="0.00"></div>`)}`,d=>{checkDate(d.date);if(config.kind&&d.kind!==config.kind)throw Error('请先登记'+meta[config.kind][0]+'，再继续原操作');const value=Fin.cents(d.value),cost=d.cost?Fin.cents(d.cost):0;if(value<0||cost<0)throw Error('金额不能为负');change(s=>s.assets.push({id:uid(),name:d.name.trim(),kind:d.kind,place:(d.place||'').trim(),risk:d.risk||'未知 / 未评估',cost,snapshots:[{date:d.date,value,confirmed:false,opening:true}]}));return config.next;},'保存资产');const update=()=>{const k=$('field-kind').value;$('asset-value-label').textContent={cash:'初始余额（元）',investment:'初始投资价值（元）',item:'预计变现净残值（元）',debt:'当前欠款（元）'}[k];$('asset-boundary').textContent=k==='item'?'残值请扣除预计交易费用，成本不会重复计入财富。':'填写当天后续记账前的金额，不据此推算更早收益。';toggleFields('#asset-risk',k==='investment');toggleFields('#asset-cost',k==='item');};$('field-kind').addEventListener('change',update);update();}
 function addTx(config={}){
  if(!config||config instanceof Element)config={};
  const old=config.edit?state.transactions.find(t=>t.id===config.edit):null,template=config.template?(state.expenseTemplates||[]).find(t=>t.id===config.template):null,seed=config.draft||old||template||{};
  if(old&&(old.linked||state.transactions.some(x=>x.linked===old.id)||state.executions.some(e=>e.transaction===old.id||e.sourceTransaction===old.id)||state.assets.some(a=>a.sold===old.id)))return toast('关联记录请通过原操作处理');
  const as=state.assets.filter(a=>['cash','investment'].includes(a.kind));

  const choice=(values,value)=>values.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
  const recent=state.transactions.slice().reverse().find(t=>as.some(a=>a.id===t.asset&&a.kind==='cash'));
  const icons={'餐饮':'🍜','居住':'🏠','交通':'🚇','购物':'🛍','水电通讯':'💡','医疗':'💊','教育':'📚','娱乐':'🎮','人情':'🎁','保险':'🛡','其他':'···'};
  const recentCategories=[...new Set(state.transactions.slice().reverse().filter(t=>t.type==='expense'&&!t.linked&&t.category).map(t=>t.category))];
  const primary=[...new Set([seed.category,...recentCategories,'餐饮','交通','购物','居住','娱乐','人情','其他'].filter(c=>Fin.expenseCategories.includes(c)))].slice(0,7);
  const extra=Fin.expenseCategories.filter(c=>!primary.includes(c));
  const tile=c=>btn('tx-category',`<span aria-hidden="true">${icons[c]}</span><small>${c}</small>`,'category-choice',`data-category="${esc(c)}" aria-label="用途：${esc(c)}" aria-pressed="false"`);
  form(old?'编辑流水':'记一笔',`
   <div class="type-switch" role="group" aria-label="交易类型">${[['expense','支出'],['income','收入'],['transfer','转账'],['deposit','追加'],['withdraw','取出']].map(([v,l])=>btn('tx-type',l,'type-choice',`data-type="${v}" aria-label="${types[v]}" aria-pressed="false"`)).join('')}</div>
   <select name="type" hidden aria-label="交易类型值">${choice(Object.entries(types),seed.type||'expense')}</select>
   <div class="money-entry"><span>¥</span><input name="amount" aria-label="金额（元）" inputmode="none" autocomplete="off" maxlength="16" required placeholder="0.00" value="${config.draft?esc(seed.amount||''):seed.amount?(seed.amount/100).toFixed(2):''}">${btn('tx-clear','清空','amount-clear','aria-label="清空金额"')}</div>
   <div id="tx-expense"><input name="category" type="hidden" value="${esc(seed.category||'')}"><input name="nature" type="hidden" value="${esc(seed.nature||'variable')}">
    <div class="category-grid" role="group" aria-label="支出用途">${primary.map(tile).join('')}${btn('tx-categories','<span>＋</span><small>全部用途</small>','category-choice')}</div>

   </div>

   <div id="tx-category-page" hidden><h3>选择支出用途</h3><div class="category-grid">${Fin.expenseCategories.map(tile).join('')}</div>${btn('tx-categories-done','返回记账','secondary')}</div>${btn('tx-settings','日期 / 备注 / 关联资产 →','secondary tx-settings-link')}<div id="tx-settings-page" hidden>   <div class="light-meta-row"><div id="tx-nature" class="nature-switch" role="group" aria-label="支出性质">${[['variable','日常'],['fixed','固定'],['occasional','偶发']].map(([v,l])=>btn('tx-nature',l,'nature-choice',`data-nature="${v}" aria-label="性质：${Fin.expenseNatures[v]}" aria-pressed="false"`)).join('')}</div></div><div class="quick-pickers"><section class="quick-picker" id="tx-account-picker"><h3 id="tx-account-tag">选择账户 ▾</h3><label id="tx-account-label">付款账户</label><select name="asset"><option value="">仅记收支（不关联资产）</option>${choice(as.map(a=>[a.id,a.name]),seed.asset||'')}</select></section><section class="quick-picker" id="tx-date-picker"><h3 id="tx-date-tag">今天 ▾</h3>${dateField('date',seed.date||today())}</section></div>
   <div id="tx-missing" hidden><p class="disclosure">转账与投资操作需要关联实际资产。</p>${btn('tx-add-account','添加账户并继续','secondary')}</div>
   <div id="tx-to"><label>转入账户</label><select name="to" required><option value="">请选择</option>${choice(as.map(a=>[a.id,a.name]),seed.to)}</select></div>
   <div id="tx-notes"><label>备注</label><input name="note" maxlength="100" value="${esc(seed.note||template?.name||'')}" placeholder="这笔钱花在哪儿？"><div id="tx-template">${more('保存常用模板',`<label class="check-label"><input type="checkbox" name="saveTemplate"><span>保存为常用支出模板</span></label><label>模板名称（可选）</label><input name="templateName" maxlength="80" placeholder="默认使用备注或用途"><label>重复频率（仅标记）</label><select name="frequency">${choice([['none','不固定'],['monthly','每月'],['yearly','每年']],seed.frequency||'none')}</select>`)}</div><p class="disclosure">固定：定期且金额稳定；日常：金额可变；偶发：临时花费。常用模板不会自动记账。</p></div>
   ${btn('tx-settings-done','完成，返回记账','secondary')}</div><div class="number-pad" role="group" aria-label="金额键盘">${['1','2','3','4','5','6','7','8','9','.','0','⌫'].map(k=>btn('tx-key',k,'number-key',`data-key="${k}" aria-label="${k==='⌫'?'删除一位':k==='.'?'小数点':'数字 '+k}"`)).join('')}</div>
  `,d=>{
   checkDate(d.date);const amount=positive(d.amount);
   if(d.type==='expense'&&!Fin.expenseCategories.includes(d.category))throw Error('点选一个支出用途，再保存');
   if(d.type==='transfer'&&(!d.to||d.to===d.asset))throw Error('请选择不同的转入账户');
   const account=state.assets.find(a=>a.id===d.asset);if(!account&&!['income','expense'].includes(d.type))throw Error('请选择账户');
   if(['deposit','withdraw'].includes(d.type)&&account?.kind!=='investment')throw Error('投资追加或取出请选择投资账户');
   if(['income','expense'].includes(d.type)&&account&&account.kind!=='cash')throw Error('收入或消费请选择现金账户');
   change(s=>{const t={id:old?.id||uid(),type:d.type,asset:d.asset||null,to:d.type==='transfer'?d.to:null,amount,date:d.date,note:(d.note||'').trim()};
    if(d.type==='expense'){t.category=d.category;t.nature=d.nature;}
    if(old?.sourceCategory&&['income','expense'].includes(d.type))t.sourceCategory=old.sourceCategory;
    if(old){invalidate(s,old);s.transactions=s.transactions.filter(t=>t.id!==old.id);invalidate(s,t);}s.transactions.push(t);
    if(d.type==='expense'&&d.saveTemplate){s.expenseTemplates??=[];s.expenseTemplates.push({id:uid(),name:(d.templateName||d.note||d.category).trim(),asset:d.asset||null,amount,category:d.category,nature:d.nature,frequency:d.frequency});}
   });
   return()=>{ledgerMonth=d.date.slice(0,7);render();if(old)return toast('已保存修改');toast('已记好');$('toast').innerHTML='已记好 '+btn('add-tx','再记一笔','toast-action');$('toast').style.pointerEvents='auto';};
  },old?'保存修改':'保存支出');
  $('modal').classList.add('light-entry');const f=$('entry-form');f.dataset.edit=config.edit||'';f.dataset.template=config.template||'';
  const update=()=>{
   const type=$('field-type').value;f.querySelectorAll('[data-action="tx-type"]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.type===type));b.classList.toggle('active',b.dataset.type===type);});
   toggleFields('#tx-to',type==='transfer');toggleFields('#tx-expense',type==='expense');toggleFields('#tx-nature',type==='expense');toggleFields('#tx-template',type==='expense');
   f.querySelectorAll('[data-action="tx-category"]').forEach(b=>{const selected=b.dataset.category===$('field-category').value;b.setAttribute('aria-pressed',String(selected));b.classList.toggle('active',selected);});
   f.querySelectorAll('[data-action="tx-nature"]').forEach(b=>{const selected=b.dataset.nature===$('field-nature').value;b.setAttribute('aria-pressed',String(selected));b.classList.toggle('active',selected);});
   $('tx-account-label').textContent={expense:'付款账户',income:'收款账户',transfer:'转出账户',deposit:'投入资产',withdraw:'取出资产'}[type];
   const select=$('field-asset');[...select.options].forEach(o=>{if(!o.value){o.disabled=!['income','expense'].includes(type);return;}const a=as.find(a=>a.id===o.value);o.disabled=['expense','income'].includes(type)?a.kind!=='cash':['deposit','withdraw'].includes(type)?a.kind!=='investment':false;});
   const enabled=[...select.options].filter(o=>!o.disabled);f.querySelector('[type="submit"]').disabled=!enabled.length;$('tx-missing').hidden=enabled.length>0;
   if(!enabled.length)select.value='';else if(select.selectedOptions[0]?.disabled){const recent=state.transactions.slice().reverse().find(t=>enabled.some(o=>o.value===t.asset));select.value=recent?.asset||enabled[0].value;}
   $('tx-account-tag').textContent=(select.selectedOptions[0]?.textContent||'选择账户');$('tx-date-tag').textContent=($('field-date').value===today()?'今天':$('field-date').value);
   f.querySelector('[type="submit"]').textContent=old?'保存修改':type==='transfer'?'保存转账':'保存'+types[type];
  };
  for(const name of ['type','asset','date','category','nature'])$('field-'+name).addEventListener('change',update);

  f.addEventListener('focusin',e=>{if(e.target.matches('[name="note"],[name="templateName"]'))f.querySelector('.number-pad').hidden=true;});

  if(config.draft){for(const name of ['templateName','frequency','saveTemplate']){const el=f.elements.namedItem(name);if(el&&config.draft[name]!==undefined){if(el.type==='checkbox')el.checked=!!config.draft[name];else el.value=config.draft[name];}}}update();
 }
 function txCategories(show){txSettings(show);$('tx-settings-page').hidden=true;$('tx-category-page').hidden=!show;}
 function txSettings(show){const f=$('entry-form');for(const selector of ['.type-switch','.money-entry','#tx-expense','.tx-settings-link','.number-pad'])f.querySelector(selector).hidden=show;$('tx-settings-page').hidden=!show;f.querySelector('.form-content').scrollTop=0;}
 function setTxField(name,value){const field=$('field-'+name);field.value=value;field.dispatchEvent(new Event('change'));}
 function txKey(key){const el=$('field-amount');let v=el.value;if(key==='⌫')v=v.slice(0,-1);else if(key==='.') {if(!v.includes('.'))v=(v||'0')+'.';}else if(/^[0-9]$/.test(key)&&(!v.includes('.')||v.split('.')[1].length<2)&&v.length<14)v=v==='0'?key:v+key;el.value=v;el.dispatchEvent(new Event('input'));}
 function editAsset(aid){const a=state.assets.find(a=>a.id===aid);form('编辑资产资料',`<label>资产名称</label><input name="name" maxlength="50" value="${esc(a?.name||'仅记收支')}" required><label>存放平台 / 地点</label><input name="place" maxlength="80" value="${esc(a.place)}">${a.kind==='investment'?`<label>风险标签（个人记录）</label><select name="risk">${['未知 / 未评估','低风险','中低风险','中风险','中高风险','高风险'].map(r=>`<option ${r===a.risk?'selected':''}>${r}</option>`).join('')}</select>`:''}${a.kind==='item'?`<label>购入成本（元）</label><input name="cost" inputmode="decimal" value="${((a.cost||0)/100).toFixed(2)}" required>`:''}`,d=>change(s=>{const x=s.assets.find(a=>a.id===aid);x.name=d.name.trim();x.place=d.place.trim();if(d.risk)x.risk=d.risk;if(d.cost!==undefined){x.cost=Fin.cents(d.cost);if(x.cost<0)throw Error('成本不能为负');}}),'保存资料');}
 function detail(aid){const a=state.assets.find(a=>a.id===aid);if(!a)return;const p=Fin.performance(state,a),snaps=[...a.snapshots].sort((x,y)=>y.date.localeCompare(x.date));modal(a.name,`<div class="muted">${meta[a.kind][0]} · ${esc(a.place||'未填写位置')}${a.kind==='investment'?' · '+esc(a.risk):''}${a.sold?' · 已出售':''}</div><div class="detail-value">¥ ${money(Fin.balance(state,a,today()))}</div>${!a.sold?`<div class="form-actions">${btn('snapshot','更新'+(a.kind==='item'?'残值':a.kind==='debt'?'欠款':'余额'),'primary',`data-id="${esc(a.id)}"`)}${a.kind==='item'?btn('sell','出售登记','secondary',`data-id="${esc(a.id)}"`):''}</div>`:''}${p?`<div class="detail-grid"><div><small>${p.complete?'区间收益':'余额变化（未核验）'}</small><strong>¥ ${money(p.complete?p.gain:p.last.value-p.first.value)}</strong></div><div><small>${p.rate===null?'历史年化 · XIRR':'持有期收益率'}</small><strong>${pct(p.rate===null?p.annual:p.rate)}</strong></div></div><p class="disclosure">${p.first.date} → ${p.last.date} · ${p.complete?'已扣除净投入，年化不代表未来收益。':'现金流未核验完整，收益率不可计算。'}</p>${more('收益计算依据',`<p>历史年化 · XIRR：${p.annual===null?'不可计算':pct(p.annual)}</p><p>持有期收益率：${p.rate===null?'不可计算（存在现金流或数据不足）':pct(p.rate)}</p><p class="disclosure">区间 ${p.days} 天。无解、非唯一解或数据不足时不展示确定的收益率。</p>`)}`:''}${a.kind==='item'?`<p class="muted">购入成本 ¥ ${money(a.cost||0)} · 残值变化 ¥ ${money(Fin.balance(state,a,today())-(a.cost||0))}</p><p class="disclosure">残值为手工估计，并非平台报价。</p>`:''}${more('估值历史 · '+snaps.length+' 条',`${snaps.map((v,i)=>`<div class="row"><div class="row-main"><h3>${v.date}</h3><span class="muted">${v.opening?'初始盘点（记账前）':v.confirmed?'日末 · 已核验':'日末 · 未核验'}</span></div><div class="row-right"><div class="money">¥ ${money(v.value)}</div>${i<snaps.length-1&&!a.sold?btn('remove-snapshot','删除','text-button danger',`data-id="${esc(a.id)}" data-date="${v.date}"`):''}</div></div>`).join('')}`)}${more('资产管理',`${btn('edit-asset','编辑资料','secondary',`data-id="${esc(a.id)}"`)} ${btn('delete-asset','删除资产','text-button danger',`data-id="${esc(a.id)}"`)}`)}`);}
 function snapshot(aid){const a=state.assets.find(a=>a.id===aid);if(a.sold)return toast('已售物品不能再更新残值');form('更新'+a.name,`${dateField()}<label>当天结束时金额（元）</label><input name="value" inputmode="decimal" required value="${(Fin.balance(state,a,today())/100).toFixed(2)}">${a.kind==='investment'?'<label class="check-label"><input type="checkbox" name="confirmed"><span>我已确认从上一笔估值到此日期的追加、取出、分红均已记录（没有进出也需确认）。</span></label>':''}<div class="callout">同日估值将被替换。同日流水视为已包含在金额中；之后日期的流水才会继续影响余额。</div>`,d=>{checkDate(d.date);const first=[...a.snapshots].sort((x,y)=>x.date.localeCompare(y.date))[0];if(d.date<first.date)throw Error('不能早于初始盘点');const value=Fin.cents(d.value);if(value<0)throw Error('金额不能为负');change(s=>{const x=s.assets.find(x=>x.id===aid),v=x.snapshots.find(v=>v.date===d.date);if(v){v.value=value;v.confirmed=!!d.confirmed;v.opening=false;}else x.snapshots.push({date:d.date,value,confirmed:!!d.confirmed});x.snapshots.filter(v=>v.date>d.date).forEach(v=>v.confirmed=false);});});}
 function addPlan(){const as=state.assets.filter(a=>a.kind==='investment');if(!as.length){toast('先登记投资资产，保存后继续设置定投');return addAsset({kind:'investment',next:addPlan});}form('设置定投',`<label>投入资产</label><select name="asset">${options(as)}</select><div class="fields"><div><label>每期金额（元）</label><input name="amount" inputmode="decimal" required placeholder="500.00"></div><div><label>周期</label><select name="frequency"><option value="monthly">每月</option><option value="weekly">每周</option><option value="daily">每天</option></select></div></div><label>首次计划日期</label><input name="start" type="date" value="${today()}" required>${more('名称与结束日期（可选）','<label>计划名称</label><input name="name" maxlength="60" placeholder="默认使用资产名称"><label>结束日期</label><input name="end" type="date">')}<p class="disclosure">按自然日生成计划，月末不足取最后一天。不自动扣款或顺延节假日。</p>`,d=>{if(!Fin.validDate(d.start)||(d.end&&(!Fin.validDate(d.end)||d.end<d.start)))throw Error('计划日期无效');change(s=>s.plans.push({id:uid(),name:d.name.trim()||state.assets.find(a=>a.id===d.asset).name+'定投',asset:d.asset,amount:positive(d.amount),frequency:d.frequency,start:d.start,end:d.end||null}));},'保存计划');}
 function execute(pid,date){const p=state.plans.find(p=>p.id===pid),cash=state.assets.filter(a=>a.kind==='cash'),old=state.executions.find(e=>e.plan===pid&&e.date===date);form('确认定投执行',`<div class="muted">${esc(p.name)} · 计划期次 ${date} · ¥ ${money(p.amount)}</div><label>实际状态</label><select name="status" required><option value="">请选择实际结果</option><option value="confirmed">已确认成交</option><option value="failed" ${old?.status==='failed'?'selected':''}>扣款失败</option><option value="skipped" ${old?.status==='skipped'?'selected':''}>本期跳过</option></select><div id="execute-fields"><label>资金来源</label><select name="source" required><option value="">请选择资金来源</option>${options(cash)}<option value="external">未登记的外部资金</option></select><div class="fields"><div><label>实际投入（元）</label><input name="amount" inputmode="decimal" value="${(p.amount/100).toFixed(2)}" required></div><div>${dateField('actualDate',date,'实际成交日期')}</div></div><label class="check-label"><input name="dateChecked" type="checkbox" required><span>已核对实际成交日期和金额</span></label></div>${more('核验依据（可选）','<label>备注</label><input name="note" maxlength="100" placeholder="例如：已确认份额">')}<p class="disclosure">成交才记投入；现金来源同步转出。失败或跳过不计投入。</p>`,d=>{if(!d.status)throw Error('请选择实际结果');if(d.status==='confirmed'){checkDate(d.actualDate);if(!d.source||!d.dateChecked)throw Error('请核对资金来源、日期和金额');}const amount=d.status==='confirmed'?positive(d.amount):0;change(s=>{const old=s.executions.find(e=>e.plan===pid&&e.date===date);if(old?.status==='confirmed')throw Error('本期已确认，请先删除关联流水');s.executions=s.executions.filter(e=>!(e.plan===pid&&e.date===date));const tid=d.status==='confirmed'?uid():null,sourceId=tid&&d.source!=='external'?uid():null;if(tid)s.transactions.push({id:tid,type:'deposit',asset:p.asset,to:null,amount,date:d.actualDate,note:'定投：'+p.name+(d.note?' · '+d.note:'')});if(sourceId)s.transactions.push({id:sourceId,type:'expense',asset:d.source,to:null,amount,date:d.actualDate,note:'定投转出：'+p.name,linked:tid});s.executions.push({plan:pid,date,status:d.status,amount,actualDate:d.actualDate||date,transaction:tid,sourceTransaction:sourceId});});},'保存执行结果');const update=()=>toggleFields('#execute-fields',$('field-status').value==='confirmed');$('field-status').addEventListener('change',update);update();}
 function confirm(title,text,fn){modal(title,`<div class="callout">${text}</div><div class="form-actions">${btn('close','取消','secondary')}<button type="button" id="confirm-action" class="primary">确认</button></div>`);$('confirm-action').onclick=()=>{try{fn();close();toast('操作完成');}catch(e){toast(e.message);}};}
 function sell(aid){const a=state.assets.find(a=>a.id===aid),cash=state.assets.filter(a=>a.kind==='cash');if(!cash.length)return toast('请先登记用于收款的现金账户');form('出售 · '+a.name,`<label>实际到账净额（元）</label><input name="amount" inputmode="decimal" required placeholder="扣除运费及手续费"><label>到账账户</label><select name="account">${options(cash)}</select>${dateField()}<div class="callout">按出售日将实物残值归零，并记一笔到账收入。保留物品历史。</div>`,d=>{checkDate(d.date);const amount=positive(d.amount),last=[...a.snapshots].sort((x,y)=>x.date.localeCompare(y.date)).at(-1);if(d.date<last.date)throw Error('出售日期不能早于最新估值');if(a.sold)throw Error('此物品已经出售');change(s=>{const x=s.assets.find(x=>x.id===aid);x.snapshots=x.snapshots.filter(v=>v.date!==d.date);x.snapshots.push({date:d.date,value:0,confirmed:true});const tid=uid();x.sold=tid;s.transactions.push({id:tid,type:'income',asset:d.account,to:null,amount,date:d.date,note:'出售：'+a.name});});});}

 let updateView=false,updateTimer,updateLast="";
 function updates(){updateView=true;updateLast="";$('modal-title').textContent="应用更新";updateStatus(typeof DeviceUpdater==='undefined'?{current:'0.1.6',phase:'browser',message:'请在安卓应用中检测和下载更新。'}:JSON.parse(DeviceUpdater.status()));clearInterval(updateTimer);if(typeof DeviceUpdater!=='undefined')updateTimer=setInterval(()=>{if(!$('modal').open||$('modal-title').textContent!=='应用更新'){clearInterval(updateTimer);updateView=false;return;}updateStatus(JSON.parse(DeviceUpdater.status()));},1000);}
 function updateStatus(s){if(!updateView||($('modal').open&&$('modal-title').textContent!=='应用更新'))return;const serialized=JSON.stringify(s);if(serialized===updateLast)return;updateLast=serialized;const r=s.release,busy=['checking','downloading','verifying'].includes(s.phase),percent=s.total?Math.min(100,Math.floor(s.downloaded/s.total*100)):0;modal('应用更新',`<p class="muted">当前版本 ${esc(s.current)} · GitHub Release</p><div class="callout" role="status">${esc(s.message)}</div>${r?`<h3>新版本 ${esc(r.version)}</h3><p class="muted">安装包 ${(r.size/1048576).toFixed(1)} MB</p>`:''}${['downloading','paused','verifying'].includes(s.phase)&&s.total?`<progress max="100" value="${percent}" aria-label="下载进度"></progress><p class="muted">${percent}% · ${(s.downloaded/1048576).toFixed(1)} / ${(s.total/1048576).toFixed(1)} MB</p>`:''}<div class="backup-buttons">${s.phase==='browser'?'':s.phase==='ready'?btn('update-install','安装更新'):s.phase==='downloading'?btn('update-pause','暂停下载'):!busy&&r&&s.phase!=='latest'?btn('update-download',s.downloaded?'继续下载':'下载更新'):''}${!busy&&s.phase!=='browser'?btn('update-check','检测更新','secondary'):''}${s.phase!=='browser'?btn('update-release','查看 GitHub Release','text-button'):'<a href="https://github.com/tyrantqiao/SquirrelFin/releases" target="_blank" rel="noopener">查看 GitHub Release</a>'}</div><p class="disclosure">仅检测和下载更新时联网，不上传账本。下载可断点继续；安装前核验 SHA-256、包名、版本与签名，由系统确认安装。开发签名包仅供试用。</p>${r?.notes?`<section class="inline-help"><h3>更新说明</h3><p class="release-notes">${esc(r.notes)}</p></section>`:''}`);}
 function settings(){modal('数据与备份',`<div class="callout">数据只保存在当前${native?'设备应用私有目录':'浏览器'}。${native?'卸载应用':'清除浏览器数据'}会删除记录，请定期导出。备份为明文 JSON，请妥善保存。</div><div class="backup-buttons">${btn('updates','应用更新','secondary')}${btn('export','↓ 导出完整备份')}${btn('import','↑ 从备份恢复','secondary')}${btn('demo','加载示例数据','secondary')}${btn('clear','清空全部数据','secondary danger')}</div><div class="disclosure">0.1.6 · 无登录、无服务器、无交易功能。备份恢复将替换当前记录，建议先导出。金额隐藏仅遮挡界面，不是应用锁。</div>`);}
 function importText(text){try{if(text.length>5000000)throw Error('文件过大');const next=Fin.validate(JSON.parse(text));confirm('恢复本地备份',`包含 ${next.assets.length} 项资产、${next.transactions.length} 笔流水、${next.plans.length} 个计划。确认后替换全部当前记录。`,()=>persist(next));}catch(e){toast('恢复失败：'+e.message);}}
 function exportData(){if(storageError)return toast('本地读取失败，不能导出空备份');const json=JSON.stringify(state,null,2);if(native)LocalDevice.exportBackup(json);else{const url=URL.createObjectURL(new Blob([json],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='SquirrelFin-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已生成');}}
 function demo(){confirm('体验示例数据',(state.assets.length||state.transactions.length)?'此操作替换当前记录，请先导出备份。':'加载明确标注的示例台账，体验资产、收益和定投功能。',()=>{const s=Fin.blank();s.demo=true;s.assets=[{id:'bank',name:'日常备用金',kind:'cash',place:'招商银行',risk:'低风险',cost:0,snapshots:[{date:prior(65),value:3268000,confirmed:false}]},{id:'yue',name:'余额宝',kind:'investment',place:'支付宝',risk:'低风险',cost:0,snapshots:[{date:prior(65),value:2000000,confirmed:false},{date:today(),value:2006800,confirmed:true}]},{id:'fund',name:'长期指数基金',kind:'investment',place:'基金账户',risk:'中高风险',cost:0,snapshots:[{date:prior(65),value:5000000,confirmed:false},{date:today(),value:5294000,confirmed:true}]},{id:'camera',name:'我的旅行相机',kind:'item',place:'家中 · 书房',risk:'未知 / 未评估',cost:1250000,snapshots:[{date:prior(40),value:860000,confirmed:false}]}];s.plans=[{id:'monthly',name:'每月，给未来存一点',asset:'fund',amount:100000,frequency:'monthly',start:prior(60),end:null}];for(const d of Fin.occurrences(s.plans[0],today()).slice(0,-1)){const tid=uid();s.transactions.push({id:tid,type:'deposit',asset:'fund',to:null,date:d,amount:100000,note:'定投：每月，给未来存一点'});s.executions.push({plan:'monthly',date:d,status:'confirmed',actualDate:d,amount:100000,transaction:tid});}persist(s);});}
 function ledgerImportText(){
  form('导入记账',`<p class="muted">粘贴文字账单，先预览，再保存。</p><label>账单文字</label><textarea name="ledgerText" rows="9" maxlength="150000" required placeholder="2026-09-01 支出❌ 日常 早餐 12">${esc(ledgerImportDraft.text)}</textarea><div class="import-file-action">${btn('ledger-file','选择 TXT / Markdown 文件','secondary')}</div><p class="disclosure">支持列表符号、表情和多余空格。格式：日期 收入/支出 原分类 备注 金额。</p><p class="disclosure">这是追加流水，不会替换账本。收入来源「投资」不会当作投资追加；公积金等请归入实际对应账户。</p>`,d=>{const parsed=Fin.parseLedgerText(d.ledgerText,today());ledgerImportDraft={text:d.ledgerText,...parsed};return()=>ledgerImportPreview();},'预览账单');
 }
 function importLedgerText(text){if(typeof text!=='string'||text.length>150000)return toast('账单文字最多 15 万字');ledgerImportDraft={text,rows:[],errors:[]};ledgerImportText();}
 function ledgerImportPreview(defaultAccount=''){
  const rows=ledgerImportDraft.rows,cash=state.assets.filter(a=>a.kind==='cash'),choice=(values,value)=>values.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
  form('核对导入账单',`
   <div class="toolbar"><span class="muted">识别 ${rows.length} 笔</span>${btn('ledger-import-edit','返回修改','text-button')}</div>
   <label>默认导入账户</label><select name="importAccount"><option value="">仅记收支（不关联资产）</option>${choice(cash.map(a=>[a.id,a.name]),defaultAccount)}</select>
   ${btn('ledger-import-account','登记历史现金账户','text-button')}
   <p class="disclosure">逐笔可修改账户与分类。用途、性质为建议，原分类会保留。疑似重复默认不勾选，确需保留时可手动勾选。</p>
   ${ledgerImportDraft.errors.length?`<div class="import-errors" role="alert">${ledgerImportDraft.errors.map(e=>`<p>第 ${e.line} 行：${esc(e.message)}</p>`).join('')}<p>请返回修改；有错误时不会导入任何一笔。</p></div>`:''}
   <div class="import-entries">${rows.map((r,i)=>`<section class="import-entry" data-index="${i}"><label class="import-row-select"><input type="checkbox" name="row${i}"><span class="row-main"><strong>${esc(r.note)}</strong><small>${r.date} · ${r.type==='income'?'收入':'支出'} · 原分类 ${esc(r.sourceCategory)}</small></span><span class="money">${r.type==='income'?'+':'−'}¥ ${money(r.amount)}</span></label><p class="import-row-status" role="status"></p><section class="import-adjust"><h3>调整分类与账户</h3><label>该笔账户</label><select name="account${i}"><option value="">使用上方默认账户</option>${choice(cash.map(a=>[a.id,a.name]),'')}</select>${r.type==='expense'?`<div class="fields"><div><label>支出用途</label><select name="category${i}">${choice(Fin.expenseCategories.map(c=>[c,c]),r.category)}</select></div><div><label>支出性质</label><select name="nature${i}">${choice(Object.entries(Fin.expenseNatures),r.nature)}</select></div></div>`:''}</section></section>`).join('')}</div>
  `,d=>{
   if(ledgerImportDraft.errors.length)throw Error('请先返回修正格式错误');
   const selected=collect().filter((r,i)=>d['row'+i]);if(!selected.length)throw Error('请选择至少一笔有效账单');
   const next=Fin.importLedger(state,selected,today(),uid);page='ledger';ledgerMonth=selected.map(r=>r.date).sort().at(-1).slice(0,7);ledgerFilter='all';persist(next);const count=selected.length;ledgerImportDraft={text:'',rows:[],errors:[]};return()=>toast('已导入 '+count+' 笔记账');
  },'确认导入');
  const f=$('entry-form'),submit=f.querySelector('[type="submit"]'),summary=document.createElement('p');summary.className='import-summary';f.querySelector('.submit-area').prepend(summary);
  const collect=()=>rows.map((r,i)=>({...r,asset:f.elements.namedItem('account'+i).value||$('field-importAccount').value||null,...(r.type==='expense'?{category:f.elements.namedItem('category'+i).value,nature:f.elements.namedItem('nature'+i).value}:{})}));
  const update=()=>{
   const preview=Fin.ledgerImportPreview(state,collect(),today());let income=0,expense=0,count=0,duplicates=0;
   preview.forEach((r,i)=>{const entry=f.querySelector('[data-index="'+i+'"]'),box=f.elements.namedItem('row'+i);box.disabled=!!r.error;if(!box.dataset.manual)box.checked=!r.error&&!r.duplicate;if(r.error)box.checked=false;entry.querySelector('.import-row-status').textContent=r.error||((r.duplicate?'疑似重复 · ':'')+(r.type==='expense'?r.category+' · '+Fin.expenseNatures[r.nature]: '收入来源：'+r.sourceCategory));entry.classList.toggle('has-error',!!r.error);entry.classList.toggle('is-duplicate',r.duplicate);if(box.checked){count++;if(r.type==='income')income+=r.amount;else expense+=r.amount;if(r.duplicate)duplicates++;}});
   summary.textContent='已选 '+count+' 笔 · 收入 ¥ '+money(income)+' · 支出 ¥ '+money(expense)+(duplicates?' · 含 '+duplicates+' 笔重复候选':'');submit.textContent='确认导入 '+count+' 笔';submit.disabled=!count||!!ledgerImportDraft.errors.length;
  };
  f.addEventListener('change',e=>{if(e.target.type==='checkbox')e.target.dataset.manual='1';update();});update();
 }
 function ledgerImportAccount(){const dates=ledgerImportDraft.rows.map(r=>r.date).sort();addAsset({kind:'cash',date:dates[0]||today(),next:()=>ledgerImportPreview(state.assets.at(-1).id)});}

 const actions={updates:updates,'update-check':()=>DeviceUpdater.check(),'update-download':()=>DeviceUpdater.download(),'update-pause':()=>DeviceUpdater.pause(),'update-install':()=>DeviceUpdater.install(),'update-release':()=>DeviceUpdater.openRelease(),nav:e=>{page=e.dataset.page;render();},filter:e=>{filter=e.dataset.filter;render();},'ledger-import':()=>ledgerImportText(),'ledger-import-edit':()=>ledgerImportText(),'ledger-import-account':ledgerImportAccount,'ledger-file':()=>native?LocalDevice.importLedger():$('ledger-file').click(),'add-asset':()=>addAsset(),'add-tx':()=>addTx(),'tx-type':e=>setTxField('type',e.dataset.type),'tx-category':e=>{setTxField('category',e.dataset.category);if(!$('tx-category-page').hidden)txCategories(false);},'tx-nature':e=>setTxField('nature',e.dataset.nature),'tx-key':e=>txKey(e.dataset.key),'tx-clear':()=>{$('field-amount').value='';$('field-amount').focus();},'tx-categories':()=>txCategories(true),'tx-categories-done':()=>txCategories(false),'tx-settings':()=>txSettings(true),'tx-settings-done':()=>txSettings(false),'tx-add-account':()=>{const f=$('entry-form'),draft=Object.fromEntries(new FormData(f)),edit=f.dataset.edit,template=f.dataset.template,kind=['deposit','withdraw'].includes(draft.type)?'investment':'cash';addAsset({kind,next:()=>addTx({draft,edit,template})});},'edit-tx':e=>addTx({edit:e.dataset.id}),'tx-detail':e=>txDetail(e.dataset.id),'ledger-filter':e=>{ledgerFilter=e.dataset.filter;render();},'use-template':e=>addTx({template:e.dataset.id}),'delete-template':e=>confirm('删除常用模板','仅删除模板，已记支出保留。',()=>change(s=>s.expenseTemplates=s.expenseTemplates.filter(t=>t.id!==e.dataset.id))),'add-plan':addPlan,detail:e=>detail(e.dataset.id),'edit-asset':e=>editAsset(e.dataset.id),snapshot:e=>snapshot(e.dataset.id),execute:e=>execute(e.dataset.id,e.dataset.date),sell:e=>sell(e.dataset.id),close,export:exportData,import:()=>native?LocalDevice.importBackup():$('import-file').click(),demo,clear:()=>confirm('清空本地数据','全部资产、流水和定投记录都会删除，无法撤销。请先导出备份。',()=>persist(Fin.blank())), 'delete-asset':e=>{const aid=e.dataset.id;if((state.expenseTemplates||[]).some(t=>t.asset===aid)||state.transactions.some(t=>t.asset===aid||t.to===aid)||state.plans.some(p=>p.asset===aid)||state.assets.find(a=>a.id===aid).sold)return toast('请先处理关联流水、常用模板、计划或出售记录');confirm('删除资产','该资产及全部估值历史将删除。',()=>change(s=>s.assets=s.assets.filter(a=>a.id!==aid)));},'delete-plan':e=>confirm('删除定投计划','删除计划与核验状态，已经登记的投入流水会保留。',()=>change(s=>{s.plans=s.plans.filter(p=>p.id!==e.dataset.id);s.executions=s.executions.filter(x=>x.plan!==e.dataset.id);})), 'delete-tx':e=>{if(state.assets.some(a=>a.sold===e.dataset.id))return toast('出售到账记录需要保留，以维持实物与资金一致');confirm('删除流水','余额和收益重新计算；定投关联的投入和转出会一起删除，对应期次恢复待核验。',()=>change(s=>{const tx=s.transactions.find(t=>t.id===e.dataset.id),ex=s.executions.find(x=>x.transaction===tx.id||x.sourceTransaction===tx.id),ids=new Set([tx.id]);if(ex){if(ex.transaction)ids.add(ex.transaction);if(ex.sourceTransaction)ids.add(ex.sourceTransaction);}s.transactions.forEach(t=>{if(t.linked===tx.id)ids.add(t.id);if(tx.linked)ids.add(tx.linked);});s.transactions.filter(t=>ids.has(t.id)).forEach(t=>invalidate(s,t));s.transactions=s.transactions.filter(t=>!ids.has(t.id));s.executions=s.executions.filter(x=>!ids.has(x.transaction)&&!ids.has(x.sourceTransaction));}));},'remove-snapshot':e=>confirm('删除估值','使用较早估值与后续流水重新计算，后续投资估值需重新核验。',()=>change(s=>{const a=s.assets.find(a=>a.id===e.dataset.id);if(a.sold)throw Error('已售物品估值不能删除');a.snapshots=a.snapshots.filter(v=>v.date!==e.dataset.date);a.snapshots.filter(v=>v.date>e.dataset.date).forEach(v=>v.confirmed=false);} ))};
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();try{if(storageError&&!['close','clear','import'].includes(el.dataset.action))return toast('本地数据读取失败，请先恢复备份或明确清空');actions[el.dataset.action]?.(el);}catch(err){toast(err.message);}});
 document.addEventListener('change',e=>{if(e.target.id==='ledger-month'&&/^\d{4}-\d{2}$/.test(e.target.value)&&Fin.validDate(e.target.value+'-01')&&e.target.value<=today().slice(0,7)){ledgerMonth=e.target.value;render();}});
 document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"]')){e.preventDefault();e.target.click();}});
 $('settings').onclick=settings;$('privacy').onclick=()=>{hidden=!hidden;render();};$('close-modal').onclick=close;
 $('import-file').onchange=async e=>{try{const f=e.target.files[0];if(f){if(f.size>5000000)toast('文件过大');else importText(await f.text());}}catch(err){toast('文件读取失败');}e.target.value='';};
 try{const raw=native?LocalDevice.read():localStorage.getItem('squirrelfin.v1');if(raw==='__READ_ERROR__')throw Error('文件读取失败');if(raw)state=Fin.validate(JSON.parse(raw));}catch(e){storageError=true;setTimeout(()=>{settings();toast('本地数据无法读取，原数据未覆盖。请恢复备份或明确清空。');},100);}
 function fitViewport(){document.documentElement.style.setProperty('--view-height',(window.visualViewport?.height||window.innerHeight)+'px');}
 window.visualViewport?.addEventListener('resize',fitViewport);window.addEventListener('resize',fitViewport);fitViewport();
 $('ledger-file').onchange=async e=>{try{const f=e.target.files[0];if(f){if(f.size>600000)toast('账单文件不能超过 600 KB');else importLedgerText(await f.text());}}catch(error){toast('读取账单失败，请重试');}e.target.value='';};
 const route=location.hash.slice(1);if(['overview','assets','ledger','plans'].includes(route))page=route;render();
 return {toast,importText,importLedgerText,back,updateStatus};
})();
